// <auto-generated />
import useSWR from 'swr';
import useSWRMutation from 'swr/mutation';
import { useApiService } from './useApiService';
import type { ApiResult } from '../types/ApiResult';
import type { ResourceQuery } from '../models';

export const resourcesKeys = {
  all: ['resources'] as const,
  detail: (id: string) => ['resources', id] as const,
};

/** List resources */
export function useListResources() {
  const api = useApiService();

  return useSWR(
    resourcesKeys.all,
    async () => {
      const result = await api.resources.listResources();
      if (result.status === 'ok' || result.status === 'created') {
        return result.data;
      }
      throw result.error;
    },
  );
}

/** Query resources with a body */
export function useQueryResources(body: ResourceQuery) {
  const api = useApiService();

  return useSWR(
    [...resourcesKeys.all, 'queryResources', body] as const,
    async () => {
      const result = await api.resources.queryResources(body);
      if (result.status === 'ok' || result.status === 'created') {
        return result.data;
      }
      throw result.error;
    },
  );
}

/** Link a resource (custom verb) */
export function useLinkResource() {
  const api = useApiService();

  return useSWRMutation(
    resourcesKeys.all,
    async () => {
      return api.resources.linkResource();
    },
  );
}